variante_1.css:
#rating-display-1 .rating-star {
  color: var(--sl-border); /* Cor padrão para estrelas não preenchidas */
  fill: currentColor;
  display: inline-block;
  vertical-align: middle;
}

/* Preenche as primeiras 4 estrelas */
#rating-display-1 .rating-star:nth-child(-n+4) {
  color: var(--sl-primary); /* Cor preenchida */
}

/* Para a 5ª estrela (a meia estrela) */
#rating-display-1 .rating-star:nth-child(5) {
  position: relative;
  color: var(--sl-border); /* Cor base para a estrela inteira */
}

#rating-display-1 .rating-star:nth-child(5)::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--sl-primary); /* Cor para a metade preenchida */
  clip-path: inset(0 50% 0 0); /* Mostra apenas a metade esquerda */
  pointer-events: none;
}

