document.addEventListener('DOMContentLoaded', () => {
  const usefulVotingContainer = document.getElementById('useful-voting-4');
  if (!usefulVotingContainer) return;

  const usefulBtn = usefulVotingContainer.querySelector('[data-vote="useful"]');
  const notUsefulBtn = usefulVotingContainer.querySelector('[data-vote="not-useful"]');
  const usefulCountSpan = usefulVotingContainer.querySelector('.useful-count');
  const notUsefulCountSpan = usefulVotingContainer.querySelector('.not-useful-count');

  const storageKeyPrefix = 'ia-balcao-voting-';
  // Use data-content-id for unique content identification, fallback to 'default-content'
  const contentId = usefulVotingContainer.dataset.contentId || 'default-content'; 
  const usefulStorageKey = storageKeyPrefix + contentId + '-useful';
  const notUsefulStorageKey = storageKeyPrefix + contentId + '-not-useful';
  const hasVotedStorageKey = storageKeyPrefix + contentId + '-voted';

  let usefulCount = parseInt(localStorage.getItem(usefulStorageKey) || '0', 10);
  let notUsefulCount = parseInt(localStorage.getItem(notUsefulStorageKey) || '0', 10);
  let hasVoted = localStorage.getItem(hasVotedStorageKey) === 'true';

  const updateCounts = () => {
    usefulCountSpan.textContent = usefulCount;
    notUsefulCountSpan.textContent = notUsefulCount;
  };

  const disableButtons = () => {
    usefulBtn.disabled = true;
    notUsefulBtn.disabled = true;
    usefulBtn.classList.add('disabled');
    notUsefulBtn.classList.add('disabled');
  };

  const handleVote = (type) => {
    if (hasVoted) return;

    if (type === 'useful') {
      usefulCount++;
      localStorage.setItem(usefulStorageKey, usefulCount);
    } else if (type === 'not-useful') {
      notUsefulCount++;
      localStorage.setItem(notUsefulStorageKey, notUsefulCount);
    }
    hasVoted = true;
    localStorage.setItem(hasVotedStorageKey, 'true');
    updateCounts();
    disableButtons();
  };

  usefulBtn.addEventListener('click', () => handleVote('useful'));
  notUsefulBtn.addEventListener('click', () => handleVote('not-useful'));

  updateCounts();
  if (hasVoted) {
    disableButtons();
  }
});
